const root = join(import.meta.dir, "..");

describe("correo", () => {
  test("lee el texto de un mensaje multipart", () => {
    const raw = [
      "From: shipment-tracking@amazon.com",
      "Subject: Shipped",
      "MIME-Version: 1.0",
      "Content-Type: multipart/alternative; boundary=bound",
